interface Props extends React.SVGProps<SVGSVGElement> {
  name: string;
  extra?: string;
  filled?: boolean;
}

export function Icon({ name, extra = "", filled, ...rest }: Props) {
  const cls = ["icon", filled ? "star-icon" : "", extra].filter(Boolean).join(" ");
  return (
    <svg className={cls} aria-hidden="true" {...rest}>
      <use href={`#i-${name}`} />
    </svg>
  );
}